JS_OUT = REPO_ROOT / "src" / "ui" / "src" / "utils" / "engineCatalog.generated.js"
MD_OUT = REPO_ROOT / "docs" / "architecture" / "rule-catalog.md"

BANNER = (
    "// GENERATED by scripts/render_catalog.py from src/catalog/engines/*.toml -- do not edit.\n"
    "// Change the engine's TOML file, then run: uv run python scripts/render_catalog.py\n"
)


def _js_string(value: str) -> str:
    # Single-quoted, the repo's JS style; json.dumps does the escaping.
    return "'" + json.dumps(value)[1:-1].replace("'", "\\'") + "'"


def _object(name: str, doc: str, rows: list[tuple[str, str]]) -> str:
    body = "".join(f"  {key}: {_js_string(value)},\n" for key, value in rows)
    return f"// {doc}\nexport const {name} = {{\n{body}}};\n"


def render_js(entries: tuple[EngineEntry, ...]) -> str:
    """The generated module's full text for ``entries`` (in catalog display order)."""
    cache_ids = sorted(engine_ids(status=ACTIVE, role="cache"))
    parts = [
        BANNER,
        _object(
            "ENGINE_LABELS",
            "Display name per engine id (display_name).",
            [(e.id, e.display_name) for e in entries],
        ),
        _object(
            "ENGINE_HEX",
            "Live UI colour per engine id (colors.ui).",
            [(e.id, e.colors.ui) for e in entries],
        ),
        "// Every engine id in the assignment gate's picker order (ui_picker_order).\n"
        "export const ENGINE_PICKER_ORDER = ["
        + ", ".join(_js_string(e.id) for e in sorted(entries, key=lambda e: e.ui_picker_order))
        + "];\n",
        '// Active engines whose role is a cache layer (role = "cache").\n'
        f"export const CACHE_ENGINE_IDS = [{', '.join(_js_string(i) for i in cache_ids)}];\n",
        _object(
            "ENGINE_STATUS",
            "Catalog status per engine id (status): active is a routing target, future a"
            " named placeholder (ADR-031 Decision 9), legacy an id only older reports carry.",
            [(e.id, e.status) for e in entries],
        ),
    ]
    return "\n".join(parts)


def _cell(support: EngineSupport | None) -> str:
    """The matrix cell for one engine's entry: what it does to a query's score."""
    if support is None:
        return "missing"
    if support.kind == "fit":
        return (
            f"fit {support.score}" if support.score is not None else f"fit ({support.confidence})"
        )
    if support.kind == "anti_pattern":
        return f"anti {support.severity:g}" + ("" if support.supported else ", no")
    if support.kind == "redesign":
        return f"redesign -{support.penalty}"
    if support.kind == "scan":
        return "scan"
    if support.kind == "future":
        return "future"
    if support.kind == "penalized":
        return "**no**"
    if not support.supported:
        return "no"
    return {"native": "native", "unscored": "-"}[support.kind]


def _engine_columns(entries: tuple[EngineEntry, ...]) -> list[EngineEntry]:
    """The engines a pattern file has an entry for: every engine routing can target, then
    the future-enhancement placeholders."""
    decided = engine_ids(status=(*ACTIVE, "future"))
    return [e for e in entries if e.id in decided]


def render_md(entries: tuple[EngineEntry, ...], pattern_entries: tuple[PatternEntry, ...]) -> str:
    """The rule-catalog Markdown page for ``entries`` and ``pattern_entries``."""
    columns = _engine_columns(entries)
    out = [
        "# Rule catalog: patterns x engines",
        "",
        "<!-- GENERATED by scripts/render_catalog.py from src/catalog/ -- do not edit. -->",
        "",
        "Generated from `src/catalog/engines/*.toml`, `src/catalog/patterns/*.toml`, "
        "`src/catalog/routing.toml`, `src/catalog/gates.toml` and "
        "`src/catalog/triage_signals.toml` (ADR-031 Decision 8). Change a TOML file, then run "
        "`uv run python scripts/render_catalog.py`. Field definitions: "
        "`src/shared/catalog/engines.py`, `src/shared/catalog/patterns.py` and "
        "`src/shared/catalog/routing.py`.",
        "",
        "## Engines",
        "",
        "| Engine | Id | Status | Role | System of record |",
        "|---|---|---|---|---|",
    ]
    for e in entries:
        status = "future enhancement" if e.status == "future" else e.status
        out.append(
            f"| {md_cell(e.display_name)} | `{e.id}` | {status} | {e.role} | "
            f"{'yes' if e.system_of_record else 'no'} |"
        )
    out += [
        "",
        "## Score weights",
        "",
        "How each engine weighs a query's four score dimensions (ADR-031 Decision 5), from "
        "its `[score_weights.<profile>]` tables; the first profile is the engine's default, "
        "and an engine with none uses the default split. Every engine gives cost the same "
        "weight (#1002).",
        "",
        "| Engine | Profile | Pattern match | Complexity | Performance | Cost |",
        "|---|---|---|---|---|---|",
    ]
    weighted = [(e.display_name, name, w) for e in entries for name, w in e.score_weights.items()]
    for label, name, w in [*weighted, ("Any other engine", "default", default_score_weights())]:
        shares = " | ".join(f"{round(w[d] * 100)}%" for d in SCORE_DIMENSIONS)
        out.append(f"| {md_cell(label)} | {name} | {shares} |")
    out += _routing_sections(entries)
    out += [
        "",
        "## Pattern x engine matrix",
        "",
        "Each cell is what a query showing the pattern gets on that engine: `fit N` (the "
        "engine's analysis reports it, catalog score N), `fit (level)` (reported with a "
        "confidence level instead of a score), `anti S` (reported as an anti-pattern, "
        "severity S), `native` (has the capability, never penalised), `scan` (lacks it and "
        "runs the pattern as a scan: loses the pattern's penalty only on a query that "
        "crosses its scan threshold), `redesign -N` "
        "(lacks it, bounded redesign, N-point penalty), **no** (cannot run it: takes the "
        "full penalty when another engine reports it as a fit), `no` (cannot run it, no "
        "score effect; `anti S, no` for a reported anti-pattern), `-` (no effect) or "
        "`future` (a future-enhancement placeholder: not modelled yet, never a routing "
        "candidate). "
        "Penalty is the points lost on an engine that reports it as an anti-pattern, or "
        "on every other engine when one reports it as a fit. One rule sizes it (ADR-031 "
        "Decision 8 Amendment 6): the penalty basis, the consequence the engines' public "
        "documentation states for the pattern, fixes the points ("
        + ", ".join(f"`{basis}` {points}" for basis, points in PENALTY_POINTS.items())
        + ").",
        "",
        "| Pattern | "
        + " | ".join(
            md_cell(e.display_name + (" (future)" if e.status == "future" else "")) for e in columns
        )
        + " | Penalty | Capability | Triage signal | Detectors |",
        "|---|" + "---|" * len(columns) + "---|---|---|---|",
    ]
    for p in pattern_entries:
        cells = [_cell(p.engines.get(e.id)) for e in columns]
        penalty = str(p.penalty) if p.penalty else "-"
        if p.penalty_basis:
            penalty += f" `{p.penalty_basis}`"
        if p.penalty_aliases:
            penalty += " (also " + ", ".join(f"`{a}`" for a in p.penalty_aliases) + ")"
        out.append(
            f"| [`{p.id}`](#{p.id}) | "
            + " | ".join(cells)
            + f" | {penalty} | {p.capability or '-'} | {p.triage_signal or '-'} | "
            f"{len(p.detectors) or 'none'} |"
        )
    out += ["", "## Patterns", ""]
    for p in pattern_entries:
        out += [f"### {p.id}", "", f"Name: {md_text(p.name)}."]
        if p.detectors:
            out.append("Detected by " + ", ".join(f"`{d}`" for d in p.detectors) + ".")
        else:
            out.append("No analysis reports this pattern today.")
        if p.penalty_why:
            out.append(f"Penalty: {p.penalty} (`{p.penalty_basis}`). {md_text(p.penalty_why)}")
        for label, note in (("Exemption note", p.exempt_note), ("Redesign note", p.redesign_note)):
            if note:
                out.append(f"{label}: {md_text(note)}")
        if p.scan_threshold:
            t = p.scan_threshold
            out.append(
                f"Scan threshold: {t.min_calls_per_second:g} calls per second and "
                f"{t.min_table_rows:,} table rows, both reached. {md_text(t.why)}"
            )
        if p.segment_weighting == "per_table":
            out.append(
                "Segment weighting: per table. A table's score weighs this pattern by the "
                "calls of the segment's queries that access that table, not the whole segment."
            )
        if p.write_pattern:
            out.append(
                "Writes only: no parity anchor borrows from it and no access class lists it."
            )
        out.append("")
        quiet: list[str] = []
        future: list[str] = []
        for e in columns:
            support = p.engines.get(e.id)
            if support is None:
                out.append(f"- {md_text(e.display_name)}: missing")
                continue
            if support.kind == "unscored" and support.class_score is None:
                quiet.append(e.display_name)
                continue
            if support.kind == "future":
                future.append(e.display_name)
                continue
            ref = f" ({support.catalog_id})" if support.catalog_id else ""
            if support.class_score is not None:
                ref += f", class score {support.class_score}"
                if support.parity_anchor:
                    ref += f" (parity anchor, from `{support.parity_anchor}`)"
            line = (
                f"- {md_text(e.display_name)}, {_cell(support).replace('**', '')}{ref}: "
                f"{md_text(support.why)}"
            )
            if support.guidance and support.kind in ("native", "scan"):
                line += f" Word search: {md_text(support.guidance)}"
            if bonus := _bonus_text(support):
                line += f" {bonus}"
            out.append(line)
        if quiet:
            out.append(f"- No effect on: {md_text(', '.join(quiet))}.")
        if future:
            out.append(f"- Not modelled yet (future enhancement): {md_text(', '.join(future))}.")
        out.append("")
    out += render_gaps_md(
        gap_rules(), aurora_version_lines(), {e.id: e.display_name for e in entries}
    )
    out += render_write_intents_md(
        write_intents(),
        carried_write_settings(),
        [e.id for e in _engine_columns(entries)],
        {e.id: e.display_name for e in entries},
    )
    return "\n".join(out).rstrip("\n") + "\n"


def render_write_intents_md(
    intents: tuple[WriteIntent, ...],
    settings: CarriedWriteSettings,
    engine_order: list[str],
    labels: dict[str, str],
) -> list[str]:
    """The write-intent section of the rule-catalog page (#1362)."""
    floor = settings.thresholds["carried_write_fit_floor"]
    out = [
        "## Write intents: serving a carried write the target's way",
        "",
        "Generated from `src/catalog/write_intents/*.toml` and `src/catalog/carried_writes.toml` "
        "(#1362; field definitions: `src/shared/catalog/write_intents.py`). A write group "
        "moves as one unit (ADR-031 Decision 1 Amendment 9), so it can carry a member whose "
        "own score on the group's engine is low. Below the floor, the member's intent is read "
        "from its parsed facts (`src/agents/referee/carried_writes.py`) and the designer input "
        "and the risk register name the engine's approach below; routing never reads it.",
        "",
        f"- `carried_write_fit_floor` = {floor.value}: {md_text(floor.why)}",
        "",
        "| Intent | What it is for |",
        "|---|---|",
    ]
    for intent in intents:
        out.append(f"| [`{intent.id}`](#{intent.id}) | {md_cell(intent.summary)} |")
    out.append("")
    for intent in intents:
        out += [
            f"### {intent.id}",
            "",
            f"{md_text(intent.name)}: {md_text(intent.summary)}",
            "",
            "| Engine | Approach | Documentation |",
            "|---|---|---|",
        ]
        for engine in [e for e in engine_order if e in intent.engines]:
            entry = intent.engines[engine]
            out.append(
                f"| {md_cell(labels.get(engine, engine))} | {md_cell(entry.approach)} | "
                f"{md_cell(entry.docs)} |"
            )
        out.append("")
    return out


_IMPACT_LABELS = {k: v[:1].upper() + v[1:] for k, v in GAP_IMPACT_LABELS.items()}

_MATCH_LABELS = (
    ("calls", "calls"),
    ("words", "words"),
    ("syntax", "syntax"),
    ("statement_endings", "statement endings"),
    ("statement_starts", "statement starts"),
    ("word_prefixes", "words starting with"),
    ("quoted_with", "text quoted with"),
    ("data_types", "column types"),
    ("data_type_globs", "column types like"),
    ("default_values", "column defaults like"),
    ("storage_engines", "storage engines"),
    ("collations", "collations"),
    ("index_types", "index types"),
    ("schemas_other_than", "objects in a schema other than"),
    ("routine_languages", "routine languages"),
)

_MATCH_FLAGS = (
    ("auto_increment", "auto-increment (serial, identity) columns"),
    ("uppercase_names", "table and column names with a capital letter"),
    ("partial_indexes", "partial indexes (with a WHERE predicate)"),
)


def _match_text(rule: GapRule) -> str:
    """What a rule looks for, as one Markdown line."""
    match = rule.match
    if match.always:
        return "every source of these engines"
    if match.version:
        return f"version: {match.version.replace('_', ' ')}"
    parts = [
        f"{label} " + ", ".join(f"`{v}`" for v in getattr(match, name))
        for name, label in _MATCH_LABELS
        if getattr(match, name)
    ]
    if match.unless_followed_by:
        parts.append("not before " + ", ".join(f"`{v}`" for v in match.unless_followed_by))
    if match.unless_preceded_by:
        parts.append("not after " + ", ".join(f"`{v}`" for v in match.unless_preceded_by))
    if match.extension:
        parts.append(
            f"the `{match.extension}` extension: CREATE EXTENSION, its installed C functions, "
            "or calls to "
            + ", ".join(f"`{v}`" for v in match.extension_calls)
            + " unqualified or in "
            + ", ".join(f"`{v}`" for v in match.extension_schemas)
            + " (not a user's same-named function)"
        )
    parts += [label for name, label in _MATCH_FLAGS if getattr(match, name)]
    if match.routines:
        parts.append("every procedure, function and trigger")
    return "; ".join(parts)


def render_gaps_md(
    rules: tuple[GapRule, ...], versions: dict[str, AuroraVersionLines], labels: dict[str, str]
) -> list[str]:
    """The relational-move gap rules section of the rule-catalog page (#471)."""
    out = [
        "## Relational move: version and feature gaps",
        "",
        "Generated from `src/catalog/gaps/*.toml` and `src/catalog/aurora_versions.toml` "
        "(#471; field definitions: `src/shared/catalog/gaps.py`). Synthesis checks the "
        "collection against the rules for wave 1's Aurora engine and writes the gaps to "
        "`report.json`'s `facts.relational_gaps`; routing never reads them. Impacts, most "
        "severe first: "
        + ", ".join(f"`{i}` ({_IMPACT_LABELS[i].lower()})" for i in GAP_IMPACTS)
        + ".",
        "",
        "| Aurora engine | Homogeneous sources | Version lines compared | Documentation |",
        "|---|---|---|---|",
    ]
    for engine, entry in sorted(versions.items()):
        out.append(
            f"| {md_cell(labels.get(engine, engine))} | {', '.join(entry.source_engines)} | "
            f"{', '.join(entry.lines)} | {md_cell(entry.docs)} |"
        )
    out += [
        "",
        "| Rule | Sources | Targets | Impact | Looks for |",
        "|---|---|---|---|---|",
    ]
    ordered = sorted(rules, key=lambda r: (GAP_IMPACTS.index(r.impact), r.id))
    for r in ordered:
        targets = ", ".join(labels.get(t, t) for t in r.targets)
        out.append(
            f"| [`{r.id}`](#{r.id}) | {', '.join(r.source_engines)} | {md_cell(targets)} | "
            f"{_IMPACT_LABELS[r.impact]} | {md_cell(_match_text(r))} |"
        )
    out.append("")
    for r in ordered:
        out += [
            f"### {r.id}",
            "",
            f"{md_text(r.feature)}: {_IMPACT_LABELS[r.impact].lower()}. {md_text(r.reason)}",
            "",
            f"Documentation: {md_text(r.docs)}.",
            "",
        ]
    return out


def _bonus_text(support: EngineSupport) -> str:
    """What a table showing the pattern adds to the engine's table-level score (#921)."""
    parts = []
    if support.table_bonus:
        parts.append(f"{support.table_bonus:+d} pattern match")
    if support.complexity_bonus:
        parts.append(f"{support.complexity_bonus:+d} complexity")
    text = ""
    if parts:
        text = "Table bonus: " + ", ".join(parts)
        if support.bonus_group:
            text += f" (once for the `{support.bonus_group}` group)"
        text += "."
    if support.complexity_feature:
        text += (" " if text else "") + "Counts toward the engine's feature complexity bonus."
    return text


def _threshold_rows(owner: str, thresholds: dict) -> list[str]:
    return [
        f"| {md_cell(owner)} | `{name}` | {t.value:g} | {md_cell(t.why)} |"
        for name, t in thresholds.items()
    ]


def _engine_rule_rows(entries: tuple[EngineEntry, ...]) -> list[str]:
    """The engine-specific routing rules the engine files hold, and the heterogeneous
    Aurora choice's features (#1081)."""
    labels = {e.id: e.display_name for e in entries}
    rows: list[str] = []
    for e in entries:
        if e.status != "active":
            continue
        rules = []
        if e.justification_floor is not None:
            floor = e.justification_floor
            rules.append(
                f"justification floor `{floor.kind}` (ledger reason `{floor.reason_code}`): "
                f"{floor.why}"
            )
        if e.joins_need_denormalized_design:
            rules.append(
                "a join consolidated away from engines none of which is relational or "
                "flagged like this one never lands here (it needs a denormalised design)"
            )
        if e.exact_tie_preferred:
            rules.append(
                "wins an exact heterogeneous Aurora tie no feature breaks, by maintainer rule "
                "(ADR-031 Decision 6 Amendment 1): a named-engine preference held as data"
            )
        rows += [f"| {md_cell(e.display_name)} | {md_cell(rule)} |" for rule in rules]
    features = [
        f"| `{name}` | {md_cell(labels.get(f.favours, f.favours))} | {f.basis} | {md_cell(f.why)} |"
        for name, f in routing_file().heterogeneous_features.items()
    ]
    out: list[str] = []
    if rows:
        out += [
            "",
            "Engine-specific routing rules, each an engine-file field the routing code reads "
            "instead of naming the engine (#1081):",
            "",
            "| Engine | Rule |",
            "|---|---|",
            *rows,
        ]
    if features:
        out += [
            "",
            "The source features that tip a close or tied heterogeneous Aurora call "
            "(`routing.toml`, ADR-031 Decision 6): the choice counts the features on each "
            "side, the workload ones first and the dialect ones only when no workload "
            "feature decides.",
            "",
            "| Feature | Favours | Basis | Why |",
            "|---|---|---|---|",
            *features,
        ]
    return out


def _routing_sections(entries: tuple[EngineEntry, ...]) -> list[str]:
    """The engine routing properties, thresholds, hard gates and triage signals (#921)."""
    out = [
        "",
        "## Engine routing properties",
        "",
        "From each engine file: the source engines whose own dialect it is, whether it "
        "scores a query only on the query's own matched pattern, what the reality check "
        "lets it absorb, whether a signal override onto it needs the justification floor, "
        "and the complexity points for 1, 2, ... feature patterns.",
        "",
        "| Engine | Source engines | Pattern only | Absorbs only | Override needs "
        "justification | Complexity by feature count |",
        "|---|---|---|---|---|---|",
    ]
    for e in entries:
        if e.status != "active":
            continue
        absorbs = "-"
        if e.absorbs_only:
            absorbs = ", ".join(
                [*(f"signal `{x}`" for x in e.absorbs_only.signals)]
                + [f"capability `{x}`" for x in e.absorbs_only.capabilities]
            )
        out.append(
            f"| {md_cell(e.display_name)} | "
            + (", ".join(f"`{x}`" for x in e.source_engines) or "-")
            + f" | {'yes' if e.pattern_only else 'no'} | {absorbs} | "
            f"{'yes' if e.override_needs_justification else 'no'} | "
            + (", ".join(str(x) for x in e.complexity_by_feature_count) or "-")
            + " |"
        )
    out += _engine_rule_rows(entries)
    out += [
        "",
        "## Thresholds",
        "",
        "The routing thresholds and floors: shared ones from `src/catalog/routing.toml`, "
        "an engine's own from its file's `[thresholds.<name>]`.",
        "",
        "| Applies to | Threshold | Value | Why |",
        "|---|---|---|---|",
        *_threshold_rows("Every engine", routing_file().thresholds),
    ]
    for e in entries:
        out += _threshold_rows(e.display_name, e.thresholds)
    gates = gates_file()
    out += [
        "",
        "## Hard gates",
        "",
        "From `src/catalog/gates.toml` (ADR-031 Decision 2 steps 2 and 3). An engine "
        "without a capability cannot serve a query that needs it: one showing a listed "
        "query fact or triage signal. A capability linked to a pattern capability names "
        "the same engines as those pattern files' `supported` flags (the loader checks it).",
        "",
        "| Capability | Engines | Query facts | Triage signals | Pattern capability | Why |",
        "|---|---|---|---|---|---|",
    ]
    names = {e.id: e.display_name for e in entries}
    for cap, c in gates.capabilities.items():
        out.append(
            f"| `{cap}` | "
            + md_cell(", ".join(names.get(x, x) for x in c.engines))
            + " | "
            + (", ".join(f"`{x}`" for x in c.facts) or "structural")
            + " | "
            + (", ".join(f"`{x}`" for x in c.triage_signals) or "-")
            + f" | {f'`{c.pattern_capability}`' if c.pattern_capability else '-'} | "
            f"{md_cell(c.why)} |"
        )
    out += [
        "",
        "Exclusions, checked in order: the engine cannot serve a query showing the fact.",
        "",
        "| Engine | Rule | Fact | Why (technical) | What a rejected override says |",
        "|---|---|---|---|---|",
    ]
    for r in gates.exclusions:
        fact = f"`{r.fact}`" + (f" >= {r.min}" if r.min is not None else "")
        out.append(
            f"| {md_cell(names.get(r.engine, r.engine))} | `{r.rule_id}` | {fact} | "
            f"{md_cell(r.description)} | {md_cell(r.customer_message)} |"
        )
    out += [
        "",
        "Waivers (ADR-031 Decision 2 Amendment 12): the engine serves a capability it lacks "
        "for a query showing the class fact, when the condition holds. The shared scorer "
        "still decides whether the engine wins.",
        "",
        "| Engine | Rule | Capability | Class fact | When | Why |",
        "|---|---|---|---|---|---|",
    ]
    for w in gates.waivers:
        when = "the query's table has its source of truth (its writes) on the engine"
        out.append(
            f"| {md_cell(names.get(w.engine, w.engine))} | `{w.rule_id}` | `{w.capability}` | "
            f"`{w.fact}` | {when} | {md_cell(w.why)} |"
        )
    out += [
        "",
        "## Triage signals",
        "",
        "From `src/catalog/triage_signals.toml`: the engines each signal is evidence for "
        "(detection stays in `src/agents/referee/triage.py`), and the signal overrides.",
        "",
        "| Signal | Targets | Override engine | Override rule |",
        "|---|---|---|---|",
    ]
    for name, sig in triage_signals_file().signals.items():
        out.append(
            f"| `{name}` | "
            + (md_cell(", ".join(names.get(x, x) for x in sig.targets)) or "-")
            + f" | {md_cell(names.get(sig.override_engine, sig.override_engine)) if sig.override_engine else '-'}"
            + f" | {f'`{sig.override_reason_code}`' if sig.override_reason_code else '-'} |"
        )
    return out


def _outputs() -> list[tuple[Path, str]]:
    return [
        (JS_OUT, render_js(engines())),
        (MD_OUT, render_md(engines(), patterns())),
    ]


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--check", action="store_true", help="exit 1 if a file is stale")
    args = parser.parse_args(argv)
    try:
        outputs = _outputs()
    except CatalogError as exc:
        print(f"invalid catalog: {exc}")
        return 1
    if args.check:
        stale = [
            path.relative_to(REPO_ROOT).as_posix()
            for path, expected in outputs
            if (path.read_text(encoding="utf-8") if path.exists() else "") != expected
        ]
        if stale:
            print(f"{', '.join(stale)} out of date. Run: uv run python scripts/render_catalog.py")
            return 1
        print(json.dumps({"render_catalog": "up to date"}))
        return 0
    for path, expected in outputs:
        path.write_text(expected, encoding="utf-8")
    print(json.dumps({"wrote": [path.relative_to(REPO_ROOT).as_posix() for path, _ in outputs]}))
    return 0


if __name__ == "__main__":
    sys.exit(main())
